const fs = require('node:fs');
const lines = fs.readFileSync('specs/001-bookmark-manager/tasks.md','utf8').split(/\r?\n/);
const tasks = lines.filter(l=>l.startsWith('- [ ] '));
const pattern=/^- \[ \] (T\d{3})(?: \[P\])?(?: \[US([1-5])\])? .+\/work\/.+$/;
const bad=tasks.filter(l=>!pattern.test(l));
const ids=tasks.map(l=>l.match(/T\d{3}/)?.[0]);
const seq=ids.filter((id,i)=>id!==`T${String(i+1).padStart(3,'0')}`);
const counts={shared:0,US1:0,US2:0,US3:0,US4:0,US5:0};
const parallel={total:0,US1:0,US2:0,US3:0,US4:0,US5:0,shared:0};
for(const l of tasks){const s=l.match(/\[US([1-5])\]/)?.[1];const k=s?`US${s}`:'shared';counts[k]++;if(l.includes('[P]')){parallel.total++;parallel[k]++;}}
console.log(JSON.stringify({total:tasks.length,counts,parallel,badFormat:bad.length,sequenceErrors:seq.length},null,2));
if(bad.length) console.log(bad.join('\n'));
process.exitCode=bad.length||seq.length?1:0;
