printf '%s\n' '--- unresolved markers ---'
rg -n '\[FEATURE NAME\]|\[###-|TXXX|\[Title\]|SAMPLE TASK|ACTION REQUIRED|NEEDS CLARIFICATION' specs/001-bookmark-manager/tasks.md || true
printf '%s\n' '--- post-task hooks ---'
