import type { SearchExpression } from './parser.js';
import { normalizeTag } from '../tags/normalize-tag.js';

export interface SearchableBookmark { title: string; url: string; description: string | null; notesText: string; tags: string[] }
const fold = (value: string) => value.normalize('NFKC').toLocaleLowerCase('und');

export function matchesSearch(expression: SearchExpression | null, item: SearchableBookmark): boolean {
  if (!expression) return true;
  if (expression.type === 'and') return matchesSearch(expression.left, item) && matchesSearch(expression.right, item);
  if (expression.type === 'or') return matchesSearch(expression.left, item) || matchesSearch(expression.right, item);
  if (expression.type === 'tag') return item.tags.some((tag) => normalizeTag(tag) === normalizeTag(expression.value));
  const needle = fold(expression.value);
  return [item.title, item.url, item.description || '', item.notesText, ...item.tags].some((field) => fold(field).includes(needle));
}

/work/src/shared/urls/validate-url.ts.content:
import { LIMITS } from '../config/limits.js';

export interface ValidatedUrl {
  input: string;
  parsed: URL;
}

export function validateHttpUrl(value: unknown): ValidatedUrl {
  if (typeof value !== 'string') throw new Error('Enter a web address.');
  const input = value.trim();
  if (!input) throw new Error('Enter a web address.');
  if ([...input].length > LIMITS.urlLength) throw new Error('The web address is too long.');
  let parsed: URL;
  try { parsed = new URL(input); } catch { throw new Error('Enter a complete web address, including http:// or https://.'); }
  if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') throw new Error('Only HTTP and HTTPS web addresses can be saved.');
  if (parsed.username || parsed.password) throw new Error('Web addresses containing credentials cannot be saved.');
  if (!parsed.hostname) throw new Error('Enter a web address with a host name.');
  return { input, parsed };
}

/work/src/shared/notes/schema.ts.content:
import type { RichTextDocument, RichTextMark, RichTextNode } from '../api/types.js';
import { LIMITS } from '../config/limits.js';

export const EMPTY_NOTE: RichTextDocument = { type: 'doc', content: [{ type: 'paragraph' }] };
const containers = new Set(['doc', 'paragraph', 'heading', 'bulletList', 'orderedList', 'listItem', 'blockquote']);
const blocks = new Set(['paragraph', 'heading', 'bulletList', 'orderedList', 'listItem', 'blockquote']);
const allowed = new Set([...containers, 'text', 'hardBreak']);

function validateMark(mark: unknown): asserts mark is RichTextMark {
  if (!mark || typeof mark !== 'object') throw new Error('A note contains an invalid format.');
  const item = mark as Record<string, unknown>;
  if (!['bold', 'italic', 'link'].includes(String(item.type))) throw new Error('A note contains an unsupported format.');
  const keys = Object.keys(item);
  if (item.type === 'link') {
    if (keys.some((key) => key !== 'type' && key !== 'attrs')) throw new Error('A note link contains unsupported data.');
    const attrs = item.attrs as Record<string, unknown> | undefined;
    if (!attrs || Object.keys(attrs).some((key) => key !== 'href') || typeof attrs.href !== 'string') throw new Error('A note link is invalid.');
    let url: URL;
    try { url = new URL(attrs.href); } catch { throw new Error('A note link must be a complete web address.'); }
    if (!['http:', 'https:'].includes(url.protocol)) throw new Error('A note link must use HTTP or HTTPS.');
  } else if (keys.some((key) => key !== 'type')) throw new Error('A note format contains unsupported data.');
}

export function validateNote(value: unknown): RichTextDocument {
  let nodes = 0;
  let textLength = 0;
  const visit = (raw: unknown, depth: number, root = false): RichTextNode => {
    if (!raw || typeof raw !== 'object' || Array.isArray(raw)) throw new Error('The note document is invalid.');
    if (depth > 20 || ++nodes > 5_000) throw new Error('The note is too complex.');
    const node = raw as Record<string, unknown>;
    const type = String(node.type);
    if (!allowed.has(type) || (root && type !== 'doc') || (!root && type === 'doc')) throw new Error('The note contains an unsupported block.');
    const allowedKeys = type === 'text' ? ['type', 'text', 'marks'] : type === 'heading' ? ['type', 'attrs', 'content'] : ['type', 'content'];
    if (Object.keys(node).some((key) => !allowedKeys.includes(key))) throw new Error('The note contains unsupported data.');
    if (type === 'text') {
      if (typeof node.text !== 'string') throw new Error('The note contains invalid text.');
      textLength += [...node.text].length;
      if (textLength > 100_000) throw new Error('The note is too long.');
      if (node.marks !== undefined) {
        if (!Array.isArray(node.marks)) throw new Error('The note contains invalid formatting.');
        node.marks.forEach(validateMark);
      }
    }
    if (type === 'heading') {
      const attrs = node.attrs as Record<string, unknown> | undefined;
      if (!attrs || Object.keys(attrs).some((key) => key !== 'level') || ![2, 3].includes(Number(attrs.level))) throw new Error('Only level 2 and 3 headings are supported.');
    }
    if (containers.has(type)) {
      if (node.content !== undefined && !Array.isArray(node.content)) throw new Error('The note block has invalid content.');
      const children = Array.isArray(node.content) ? node.content.map((child) => visit(child, depth + 1)) : [];
      if (type === 'doc' && children.some((child) => !blocks.has(child.type))) throw new Error('The note has an invalid top-level block.');
    }
    return structuredClone(raw) as RichTextNode;
  };
  const result = visit(value, 0, true) as RichTextDocument;
  const serialized = JSON.stringify(result);
  if (Buffer.byteLength(serialized, 'utf8') > LIMITS.noteJsonBytes) throw new Error('The formatted note is larger than 100 KiB.');
  return result;
}

/work/src/shared/urls/normalize-url.ts.content:
import { validateHttpUrl } from './validate-url.js';

/** Produce the deliberately conservative identity key approved in the spec. */
export function normalizeUrl(value: string): string {
  const { input, parsed } = validateHttpUrl(value);
  const authorityStart = input.indexOf('//') + 2;
  const tailStartCandidate = input.slice(authorityStart).search(/[/?#]/);
  const tailStart = tailStartCandidate < 0 ? input.length : authorityStart + tailStartCandidate;
  const rawTail = input.slice(tailStart);
  let port = parsed.port;
  if ((parsed.protocol === 'http:' && port === '80') || (parsed.protocol === 'https:' && port === '443')) port = '';
  const host = parsed.hostname.includes(':') ? `[${parsed.hostname.toLowerCase()}]` : parsed.hostname.toLowerCase();
  const authority = `${parsed.protocol.toLowerCase()}//${host}${port ? `:${port}` : ''}`;
  return authority + (rawTail || '/');
}

export function outboundUrl(value: string): URL {
  const { parsed } = validateHttpUrl(value);
  parsed.hash = '';
  return parsed;
}

