function renderNode(node: RichTextNode, key: number): ReactNode {
  if (node.type === 'text') {
    let content: ReactNode = node.text || '';
    for (const mark of node.marks || []) {
      if (mark.type === 'bold') content = <strong>{content}</strong>;
