  const result=useQuery({queryKey:queryKeys.bookmarks(query.toString()),queryFn:()=>api<BookmarkPage>(`/api/bookmarks?${query}`),enabled:Boolean(preferences.data)});
  const preferenceMutation=useMutation({mutationFn:(next:Partial<Preferences>)=>api<Preferences>('/api/preferences',{method:'PATCH',body:JSON.stringify(next)}),onSuccess:(value)=>client.setQueryData(queryKeys.preferences,value)});
  const update=(key:string,value:string)=>{const next=new URLSearchParams(params);if(value)next.set(key,value);else next.delete(key);next.delete('page');setParams(next,{replace:true});};
  const heading=copy.get(view)!; const syntaxError=result.error instanceof ApiClientError&&result.error.payload.code==='SEARCH_SYNTAX_ERROR';
  return <section className="page"><div className="page-heading"><div><p className="eyebrow">{view==='active'?'Collection':view==='to-read'?'Reading queue':'Stored away'}</p><h1>{heading.title}</h1></div>{view==='active'&&<Link className="button primary" to="/bookmarks/new">Add bookmark</Link>}</div>
    <div className="search-panel"><label className="search-label">Search bookmarks<input type="search" value={params.get('q')||''} onChange={e=>update('q',e.target.value)} placeholder={'Try “design systems” AND tag:research'} aria-describedby="search-help"/></label><p id="search-help" className="hint">Use quotes for an exact phrase, tag:name for a tag, and AND, OR, or parentheses to combine searches.</p>
      <div className="filters"><label><input type="checkbox" checked={params.get('favorite')==='true'} onChange={e=>update('favorite',e.target.checked?'true':'')}/> Favorites only</label><label>Tag <input value={params.get('tag')||''} onChange={e=>update('tag',e.target.value)} placeholder="Exact tag"/></label><label>Sort <select value={`${sort}:${direction}`} onChange={e=>{const [field,dir]=e.target.value.split(':');const next=new URLSearchParams(params);next.set('sort',field!);next.set('direction',dir!);setParams(next,{replace:true});preferenceMutation.mutate({sortField:field as any,sortDirection:dir as any});}}><option value="createdAt:desc">Newest added</option><option value="createdAt:asc">Oldest added</option><option value="updatedAt:desc">Recently updated</option><option value="updatedAt:asc">Least recently updated</option><option value="title:asc">Title A–Z</option><option value="title:desc">Title Z–A</option></select></label>{params.toString()&&<button className="button quiet" onClick={()=>setParams({})}>Clear filters</button>}</div></div>
    {result.isLoading&&<div className="loading" role="status">Loading bookmarks…</div>}
    {result.error&&<div className="notice error" role="alert">{syntaxError?result.error.message:'Bookmarks could not be loaded. Try again.'}</div>}
    {result.data&&<><p className="result-count" role="status">{result.data.total} {result.data.total===1?'bookmark':'bookmarks'}</p>{result.data.items.length?<BookmarkList items={result.data.items}/>:<div className="empty-state"><h2>{params.toString()?'No matching bookmarks':heading.empty}</h2>{params.toString()?<button className="button" onClick={()=>setParams({})}>Clear search and filters</button>:view==='active'?<Link className="button primary" to="/bookmarks/new">Add a bookmark</Link>:null}</div>}</>}
  </section>;
}

