-.brand { font-family: Georgia, serif; font-size: 1.45rem; font-weight: 700; text-decoration: none; }
+.site-header { position: sticky; top: 0; z-index: 10; display: flex; align-items: center; gap: 1.5rem; padding: .9rem clamp(1rem, 4vw, 3rem); border-bottom: 1px solid var(--line); background: rgb(255 253 248 / .94); backdrop-filter: blur(10px); }
+.brand, h1, h2, h3 { font-family: Georgia, 'Times New Roman', serif; }
+.brand { font-size: 1.55rem; font-weight: 700; text-decoration: none; letter-spacing: -.03em; }
 .site-header nav { display: flex; gap: 1rem; flex: 1; }
-.site-header nav a { text-decoration: none; color: #6b645a; }
-.site-header nav a.active { color: #25231f; font-weight: 700; }
-.button { display: inline-flex; align-items: center; justify-content: center; border: 0; border-radius: .7rem; padding: .72rem 1rem; text-decoration: none; cursor: pointer; }
-.primary { color: white; background: #9b3f21; }
+.site-header nav a { text-decoration: none; color: var(--muted); padding: .4rem .15rem; }
+.site-header nav a.active { color: var(--ink); font-weight: 700; border-bottom: 2px solid var(--accent); }
+.button { display: inline-flex; min-height: 42px; align-items: center; justify-content: center; border: 1px solid var(--line); border-radius: .7rem; padding: .62rem .9rem; text-decoration: none; cursor: pointer; background: var(--surface); font-weight: 650; }
+.button:disabled { opacity: .55; cursor: wait; }
+.primary { color: white; background: var(--accent); border-color: var(--accent); }
+.primary:hover { background: var(--accent-dark); }
+.quiet { background: transparent; }
+.danger { color: white; background: var(--danger); border-color: var(--danger); }
 .page { max-width: 1180px; margin: 0 auto; padding: 2rem clamp(1rem, 4vw, 3rem); }
-@media (max-width: 640px) { .site-header { flex-wrap: wrap; gap: .75rem; } .site-header nav { order: 3; width: 100%; overflow-x: auto; } }
+.narrow { max-width: 820px; }
+.page-heading { display: flex; justify-content: space-between; align-items: flex-start; gap: 1rem; margin-bottom: 1.5rem; }
+.page-heading h1, .detail-header h1 { font-size: clamp(2rem, 5vw, 3.6rem); letter-spacing: -.045em; line-height: 1.02; margin: .15rem 0 .5rem; }
+.eyebrow { color: var(--accent); text-transform: uppercase; letter-spacing: .12em; font-size: .74rem; font-weight: 800; margin: 0; }
+.hint, .muted, .host, .result-count, time { color: var(--muted); font-size: .9rem; }
+.search-panel, .bookmark-form, .notes-section { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); box-shadow: var(--shadow); padding: 1.25rem; }
+.search-label { font-weight: 700; }
+.search-label input { margin-top: .35rem; font-size: 1.05rem; }
+input, textarea, select { width: 100%; border: 1px solid #bbb1a2; border-radius: .6rem; padding: .68rem .75rem; background: #fff; }
+textarea { resize: vertical; }
+label, .field-label { display: grid; gap: .35rem; font-weight: 700; }
+.filters { display: grid; grid-template-columns: minmax(150px,.7fr) minmax(160px,1fr) minmax(190px,1.1fr) auto; gap: .8rem; align-items: end; margin-top: 1rem; }
+.filters label:first-child { display: flex; align-items: center; min-height: 42px; }
+.filters input[type=checkbox], .inline-options input { width: 1.1rem; height: 1.1rem; }
+.bookmark-grid { display: grid; grid-template-columns: repeat(auto-fill,minmax(min(100%,310px),1fr)); gap: 1rem; }
+.bookmark-card { display: grid; grid-template-rows: 150px 1fr; overflow: hidden; border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); box-shadow: var(--shadow); }
+.card-media { display: block; overflow: hidden; background: #ded5c6; text-decoration: none; }
+.card-media img { width: 100%; height: 100%; object-fit: cover; }
+.media-placeholder { display: grid; place-items: center; height: 100%; font: 700 4rem Georgia,serif; color: #786957; }
+.card-body { display: flex; flex-direction: column; padding: 1rem; }
+.card-heading { display: flex; gap: .7rem; align-items: flex-start; }
+.card-heading>div { min-width: 0; flex: 1; }
+.card-heading a { text-decoration: none; }
+.card-heading h2 { font-size: 1.3rem; line-height: 1.15; margin: 0 0 .2rem; }
+.site-icon, .detail-icon { width: 30px; height: 30px; object-fit: contain; border-radius: .35rem; }
+.site-icon-fallback { width: 30px; height: 30px; border-radius: .35rem; background: var(--soft); }
+.clamp { display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
+.tag-row, .tag-chips { display: flex; flex-wrap: wrap; gap: .4rem; }
+.tag, .tag-chip { background: var(--soft); border-radius: 999px; padding: .2rem .55rem; font-size: .82rem; }
+.tag-chip button { border: 0; background: transparent; cursor: pointer; padding: 0 0 0 .35rem; }
+.card-footer { display: flex; justify-content: space-between; align-items: end; gap: .5rem; margin-top: auto; padding-top: 1rem; }
+.card-actions { display: flex; flex-wrap: wrap; justify-content: end; gap: .4rem; }
+.card-actions .button { min-height: 34px; padding: .35rem .5rem; font-size: .82rem; }
+.result-count { margin: 1rem 0 .6rem; }
+.empty-state, .loading { text-align: center; padding: 4rem 1rem; }
+.empty-state { border: 1px dashed #bfb3a2; border-radius: var(--radius); }
+.bookmark-form { display: grid; gap: 1.2rem; }
+.inline-options { border: 0; padding: 0; display: flex; gap: 1.5rem; }
+.inline-options legend { font-weight: 700; margin-bottom: .4rem; }
+.inline-options label { display: flex; align-items: center; }
+.metadata-preview { display: flex; position: relative; min-height: 110px; border-radius: .7rem; overflow: hidden; background: var(--soft); }
+.metadata-preview>img:first-child { width: 100%; max-height: 240px; object-fit: cover; }
+.metadata-preview .preview-icon { position: absolute; left: .75rem; bottom: .75rem; width: 48px; height: 48px; background: white; padding: 4px; border-radius: .5rem; }
+.note-editor { border: 1px solid #bbb1a2; border-radius: .65rem; overflow: hidden; background: #fff; }
+.note-toolbar { display: flex; gap: .25rem; flex-wrap: wrap; padding: .45rem; background: var(--soft); border-bottom: 1px solid var(--line); }
+.note-toolbar button { border: 1px solid transparent; background: transparent; border-radius: .35rem; padding: .35rem .5rem; cursor: pointer; }
+.note-toolbar button[aria-pressed=true] { border-color: var(--accent); background: white; color: var(--accent-dark); }
+.note-editor-content { min-height: 170px; padding: .6rem .8rem; }
+.note-editor-content p { margin: .45rem 0; }
+.notice { border-radius: .65rem; padding: .75rem 1rem; }
+.warning { background: #fff3d1; border: 1px solid #d6a847; }
+.error { background: #ffe4e1; border: 1px solid #cf8177; }
+.status-region:empty { display: none; }
+.back-link { display: inline-block; margin-bottom: 1rem; color: var(--muted); }
+.detail-page { max-width: 900px; }
+.detail-preview { width: 100%; max-height: 420px; object-fit: cover; border-radius: var(--radius); margin-bottom: 1.5rem; }
+.detail-header { display: flex; justify-content: space-between; align-items: flex-start; gap: 1rem; }
+.detail-icon { width: 42px; height: 42px; float: left; margin-right: .75rem; }
+.favorite-button { border: 0; background: none; color: var(--accent); cursor: pointer; padding: .5rem; white-space: nowrap; }
+.destination { display: inline-block; color: var(--accent-dark); overflow-wrap: anywhere; }
+.lead { font-size: 1.16rem; max-width: 70ch; }
+.timestamps { display: flex; gap: 2rem; color: var(--muted); font-size: .9rem; }
+.timestamps div { display: flex; gap: .4rem; }.timestamps dd { margin: 0; }
+.notes-section { margin: 2rem 0; }.notes-section h2 { margin-top: 0; }
+.formatted-note { overflow-wrap: anywhere; }.formatted-note blockquote { border-left: 3px solid var(--accent); margin-left: 0; padding-left: 1rem; color: var(--muted); }
+.detail-actions, .form-actions, .dialog-actions { display: flex; flex-wrap: wrap; gap: .65rem; }
+.modal-overlay { position: fixed; inset: 0; z-index: 30; display: grid; place-items: center; padding: 1rem; background: rgb(30 25 20 / .55); }
+.modal { max-width: 480px; width: 100%; }.dialog { background: var(--surface); border-radius: var(--radius); padding: 1.5rem; box-shadow: 0 30px 80px rgb(0 0 0 / .3); }.dialog h2 { margin-top: 0; }

/work/src/client/styles/responsive.css.content:
@media (max-width: 700px) {
  .site-header { flex-wrap: wrap; gap: .65rem; }
  .site-header nav { order: 3; width: 100%; overflow-x: auto; justify-content: space-between; }
  .site-header>.button { margin-left: auto; }
  .page { padding-top: 1.35rem; }
  .page-heading, .detail-header { align-items: stretch; flex-direction: column; }
  .filters { grid-template-columns: 1fr; }
  .bookmark-grid { grid-template-columns: 1fr; }
  .card-footer { align-items: flex-start; flex-direction: column; }
  .card-actions { justify-content: flex-start; }
  .timestamps { flex-direction: column; gap: .25rem; }
  .inline-options { flex-direction: column; gap: .5rem; }
  .note-toolbar { overflow-x: auto; flex-wrap: nowrap; }
}
@media (max-width: 380px) {
  .site-header { padding: .75rem; }
  .site-header .button { padding-inline: .65rem; }
  .page { padding-inline: .75rem; }
  .search-panel, .bookmark-form, .notes-section { padding: .85rem; }
}

