describe('database migrations',()=>{it('enables integrity controls and creates every approved index',()=>{const db=createTestDatabase();expect(db.pragma('foreign_keys',{simple:true})).toBe(1);const tables=(db.prepare("SELECT name FROM sqlite_master WHERE type='table'").all() as Array<{name:string}>).map(row=>row.name);expect(tables).toEqual(expect.arrayContaining(['bookmarks','media_assets','metadata_drafts','tags','bookmark_tags','preferences','schema_migrations']));const indexes=(db.prepare("SELECT name FROM sqlite_master WHERE type='index'").all() as Array<{name:string}>).map(row=>row.name);expect(indexes).toEqual(expect.arrayContaining(['bookmarks_active_created','bookmarks_read_created','bookmark_tags_by_tag','metadata_drafts_expiry']));expect(()=>db.prepare("INSERT INTO bookmarks(id,url,normalized_url,title,notes_json,notes_text,favorite,to_read,created_at,updated_at) VALUES('x','https://x','https://x/','', '{}','',0,0,1,1)").run()).toThrow();db.close();});});

/work/tests/e2e/bookmark-manager.spec.ts.content:
import { expect,test } from '@playwright/test';
import AxeBuilder from '@axe-core/playwright';

test('save, find, read, archive, restore, and delete a bookmark',async({page},testInfo)=>{
  const slug=`pw-${testInfo.project.name}-${Date.now()}`;const url=`https://example.com/${slug}`;const title=`Playwright ${testInfo.project.name}`;
  await page.goto('/bookmarks/new');
  await page.getByLabel('Web address').fill(url);
  await page.getByLabel('Title').fill(title);
  await page.getByLabel('Description').fill('A browser-tested bookmark');
  await page.getByLabel('Tags').fill('Browser test');await page.getByLabel('Tags').press('Enter');
  await page.getByLabel('To read').check();
  await page.getByRole('button',{name:'Save bookmark'}).click();
  await expect(page).toHaveURL(/\/bookmarks\/[0-9a-f-]+$/u);
  await expect(page.getByRole('heading',{level:1,name:title})).toBeVisible();

  await page.getByRole('link',{name:'To Read'}).click();
  await expect(page.getByRole('heading',{level:2,name:title})).toBeVisible();
  await page.getByRole('button',{name:'Mark read'}).click();
  await expect(page.getByRole('heading',{level:2,name:title})).toHaveCount(0);

  await page.getByRole('link',{name:'Bookmarks',exact:true}).click();
  await page.getByRole('link',{name:title}).click();
  await page.getByRole('button',{name:'Archive'}).click();
  await expect(page).toHaveURL('/archive');
  await expect(page.getByRole('heading',{level:2,name:title})).toBeVisible();
  await page.getByRole('button',{name:'Restore'}).click();
  await expect(page.getByRole('heading',{level:2,name:title})).toHaveCount(0);

  await page.getByRole('link',{name:'Bookmarks',exact:true}).click();
  await page.getByRole('link',{name:title}).click();
  await page.getByRole('button',{name:'Delete permanently'}).click();
  await expect(page.getByRole('alertdialog')).toContainText(title);
  await page.getByRole('button',{name:'Cancel'}).click();
  await expect(page.getByRole('heading',{level:1,name:title})).toBeVisible();
  await page.getByRole('button',{name:'Delete permanently'}).click();
  await page.getByRole('alertdialog').getByRole('button',{name:'Delete permanently'}).click();
  await expect(page).toHaveURL('/');
  await expect(page.getByText(title)).toHaveCount(0);
});

test('duplicate paste navigates to the existing bookmark',async({page},testInfo)=>{
  const slug=`duplicate-${testInfo.project.name}-${Date.now()}`;const title=`Only one ${testInfo.project.name}`;
  await page.goto('/bookmarks/new');await page.getByLabel('Web address').fill(`https://EXAMPLE.com:443/${slug}`);await page.getByLabel('Title').fill(title);await page.getByRole('button',{name:'Save bookmark'}).click();await expect(page.getByRole('heading',{level:1,name:title})).toBeVisible();
  const detailUrl=page.url();await page.goto('/bookmarks/new');await page.getByLabel('Web address').fill(`https://example.com/${slug}`);await expect(page).toHaveURL(detailUrl,{timeout:5_000});await expect(page.getByRole('status')).toContainText('Already saved');
});

test('primary routes are accessible and never overflow the viewport',async({page})=>{
  for(const path of ['/','/to-read','/archive','/bookmarks/new']){await page.goto(path);await page.locator('[data-harness-ready="true"]').waitFor();expect(await page.evaluate(()=>document.documentElement.scrollWidth<=window.innerWidth)).toBe(true);const scan=await new AxeBuilder({page}).disableRules(['color-contrast']).analyze();expect(scan.violations.filter(item=>['serious','critical'].includes(item.impact||''))).toEqual([]);}
});

