import{chromium}from'playwright';const b=await chromium.launch();const p=await b.newPage({viewport:{width:320,height:720}});for(const path of ['/','/to-read','/archive','/bookmarks/new']){await p.goto('http://127.0.0.1:4000'+path);await p.waitForSelector('[data-harness-ready=true]');console.log(path,await p.evaluate(()=>({sw:document.documentElement.scrollWidth,iw:innerWidth,bad:[...document.querySelectorAll('*')].map(e=>({tag:e.tagName,c:e.className,r:e.getBoundingClientRect().right,w:e.scrollWidth})).filter(x=>x.r>innerWidth+1||x.w>innerWidth+1).slice(0,10)})));}await b.close();
NODE

