describe('bookmark creation persistence',()=>{it('survives close/reopen and rolls back invalid multi-table input',()=>{const directory=mkdtempSync(join(tmpdir(),'keepsake-create-'));const path=join(directory,'db.sqlite3');let db=createDatabase(path);migrate(db);const service=new BookmarkService(db);const bookmark=service.create({url:'https://example.com/a',title:'Persisted',notes:EMPTY_NOTE,tags:['One'],favorite:false,toRead:false});expect(()=>service.create({url:'https://example.com/b',title:'Invalid',notes:EMPTY_NOTE,tags:Array.from({length:21},(_,i)=>`t${i}`),favorite:false,toRead:false})).toThrow();expect((db.prepare('SELECT count(*) AS count FROM bookmarks').get() as {count:number}).count).toBe(1);db.close();db=createDatabase(path);migrate(db);expect(new BookmarkService(db).get(bookmark.id).tags[0]?.name).toBe('One');db.close();rmSync(directory,{recursive:true});});});

