export interface ComboBoxProps<T, M extends SelectionMode = 'single'>
  extends
    Omit<
      AriaComboBoxProps<T, M>,
      | 'children'
      | 'placeholder'
      | 'label'
      | 'description'
      | 'errorMessage'
      | 'validationState'
      | 'validationBehavior'
