            ref: popoverRef,
            triggerRef,
            scrollRef: listBoxRef,
            placement: 'bottom start',
            isNonModal: true,
            trigger: 'ComboBox',
            style: {'--trigger-width': menuWidth} as React.CSSProperties,
            clearContexts: CLEAR_CONTEXTS
