tests/integration/db/migrations.test.ts:12:  it('enables integrity controls and creates every approved index',()=>{const db=createTestDatabase();expect(db.pragma('foreign_keys',{simple:true})).toBe(1);expect(db.pragma('trusted_schema',{simple:true})).toBe(0);const tables=(db.prepare("SELECT name FROM sqlite_master WHERE type='table'").all() as Array<{name:string}>).map(row=>row.name);expect(tables).toEqual(expect.arrayContaining(['bookmarks','media_assets','metadata_drafts','tags','bookmark_tags','preferences','schema_migrations']));const indexes=(db.prepare("SELECT name FROM sqlite_master WHERE type='index'").all() as Array<{name:string}>).map(row=>row.name);expect(indexes).toEqual(expect.arrayContaining(['bookmarks_active_created','bookmarks_read_created','bookmark_tags_by_tag','metadata_drafts_expiry']));db.close();});
tests/integration/db/migrations.test.ts:13:  it('enforces key CHECK, UNIQUE, and foreign-key constraints',()=>{const db=createTestDatabase();const insert=db.prepare(bookmarkSql);expect(()=>insert.run('x','https://x','https://x/','', '{}','',0,0,1,1)).toThrow();insert.run('one','https://one','https://one/','One','{}','',0,0,1,1);expect(()=>insert.run('two','https://two','https://one/','Two','{}','',0,0,1,1)).toThrow();expect(()=>db.prepare('UPDATE bookmarks SET favorite=2 WHERE id=?').run('one')).toThrow();expect(()=>db.prepare("INSERT INTO bookmark_tags(bookmark_id,tag_id) VALUES('missing',999)").run()).toThrow();expect(()=>db.prepare("INSERT INTO tags(name,normalized_name,created_at) VALUES('','',1)").run()).toThrow();expect(()=>db.prepare("UPDATE preferences SET sort_field='bad' WHERE id=1").run()).toThrow();expect(()=>db.prepare("INSERT INTO media_assets(id,mime_type,bytes,byte_length,width,height,created_at) VALUES(?, 'image/png', ?, 1, 129, 1, 1)").run('a'.repeat(64),Buffer.from([1]))).toThrow();db.close();});
