tests/integration/security/metadata-security.test.ts:2:describe('metadata security regression',()=>{it.each(['0.0.0.0','10.0.0.1','100.64.0.1','127.0.0.1','169.254.169.254','172.31.255.255','192.0.2.1','192.168.0.1','198.18.0.1','198.51.100.1','203.0.113.1','224.0.0.1','255.255.255.255','::','::1','::ffff:10.0.0.1','fc00::1','fe80::1','ff02::1','2001:db8::1'])('blocks special address %s',address=>expect(isPublicAddress(address)).toBe(false));it.each(['localhost','service.local','thing.test','name.invalid','router.home.arpa','intranet'])('blocks special hostname %s',hostname=>expect(()=>validateOutboundHostname(hostname)).toThrow());it('blocks credentials, private redirects, unsafe ports, and cancellation at the guarded boundary',async()=>{await expect(guardedFetch('https://user:pass@example.com')).rejects.toThrow();await expect(guardedFetch('http://127.0.0.1')).rejects.toThrow();await expect(guardedFetch('https://example.com:444')).rejects.toThrow();const controller=new AbortController();controller.abort();await expect(guardedFetch('https://example.com',{signal:controller.signal})).rejects.toThrow();});});
tests/integration/security/content-security.test.ts:2:describe('stored content and browser policy',()=>{let fixture:Awaited<ReturnType<typeof createTestApp>>;beforeEach(async()=>{fixture=await createTestApp();});afterEach(()=>fixture.close());it('sends restrictive browser headers',async()=>{const response=await fixture.app.inject({url:'/api/health'});expect(response.headers['content-security-policy']).toContain("script-src 'self'");expect(response.headers['x-frame-options']).toBe('DENY');expect(response.headers['x-content-type-options']).toBe('nosniff');});it('rejects stored script nodes and cross-origin mutation',async()=>{const unsafe={url:'https://example.com',title:'Unsafe',notes:{type:'doc',content:[{type:'script',content:[{type:'text',text:'alert(1)'}]}]},tags:[],favorite:false,toRead:false};expect((await fixture.app.inject({method:'POST',url:'/api/bookmarks',payload:unsafe})).statusCode).toBe(422);expect((await fixture.app.inject({method:'POST',url:'/api/bookmarks',headers:{origin:'https://evil.example',host:'keepsake.test'},payload:{...unsafe,notes:EMPTY_NOTE}})).statusCode).toBe(403);});});
tests/integration/metadata/guarded-fetch.test.ts:5:describe('guarded metadata API',()=>{let app:FastifyInstance,db:BookmarkDatabase;beforeEach(async()=>{db=createTestDatabase();app=await buildApp({db},false);await app.ready();});afterEach(async()=>{await app.close();db.close();});it.each(['http://127.0.0.1/','http://2130706433/','http://[::ffff:127.0.0.1]/','http://localhost/','https://example.com:444/'])('returns safe fallback for blocked %s',async url=>{const response=await app.inject({method:'POST',url:'/api/metadata/preview',payload:{url}});expect(response.statusCode).toBe(200);expect(response.json()).toMatchObject({kind:'metadata',status:'unavailable'});});it('rejects credentials before retrieval',async()=>{const response=await app.inject({method:'POST',url:'/api/metadata/preview',payload:{url:'https://user:pass@example.com/'}});expect(response.statusCode).toBe(422);expect(response.json().code).toBe('VALIDATION_ERROR');});});

